/* @author MILO-GAO(高振銘)@2020 */ package secure2020.data;import java.util.ArrayList;import java.util.HashMap;import java.util.List;import java.util.Map;import page2020.core.Bean;import page2020.core.Prop;import page2020.view.Element;public class SecureUser extends Bean<SecureUser> {	private Element<?, ?> navbar;	private Element<?, ?> menu;	private Map<String, Element<?, ?>> navbars = new HashMap<String, Element<?, ?>>();	private Map<String, Element<?, ?>> menus = new HashMap<String, Element<?, ?>>();	private String sysCode;	private List<String> permission = new ArrayList<String>();	private Prop<SecureUser, Object> prop = new Prop<SecureUser, Object>();	private Long accountId;	private String domain;	private String username;	private String fullname;	private String title;	private String lang;	public SecureUser() {		super();	}	public void prop(String name, Object entity) {		this.prop.add(name, entity);	}	public Object prop(String name) {		return this.prop.value(name);	}	public void remove(String name) {		this.prop.remove(name);	}	public String string(String name) {		try {			Object object = this.prop.value(name);			if (object != null) {				return (String) object;			}		} catch (Exception ex) {}		return "";	}	public int integer(String name) {		try {			Integer value = (Integer) this.prop.value(name);			if (value != null) {				return value.intValue();			}		} catch (Exception ex) {}		return 0;	}	public Long id(String name) {		try {			Long id = (Long) this.prop.value(name);			if (id != null) {				return id;			}					} catch (Exception ex) {}		return 0L;	}	public boolean bool(String name) {		try {			Boolean bool = (Boolean) this.prop.value(name);			if (bool != null) {				return bool.booleanValue();			}		} catch (Exception ex) {}		return false;	}	@Override	public String toString() {		return "SecureUser [sysCode=" + sysCode + ", permission=" + permission.size() + ", accountId=" + accountId				+ ", domain=" + domain + ", username=" + username + ", fullname=" + fullname + ", title=" + title				+ ", lang=" + lang + "]";	}	public Element<?, ?> getNavbar() {		return navbar;	}	public void setNavbar(Element<?, ?> navbar) {		this.navbar = navbar;	}	public Element<?, ?> getMenu() {		return menu;	}	public void setMenu(Element<?, ?> menu) {		this.menu = menu;	}	public Map<String, Element<?, ?>> getNavbars() {		return navbars;	}	public void setNavbars(Map<String, Element<?, ?>> navbars) {		this.navbars = navbars;	}	public Map<String, Element<?, ?>> getMenus() {		return menus;	}	public void setMenus(Map<String, Element<?, ?>> menus) {		this.menus = menus;	}	public String getSysCode() {		return sysCode;	}	public void setSysCode(String sysCode) {		this.sysCode = sysCode;	}	public List<String> getPermission() {		return permission;	}	public void setPermission(List<String> permission) {		this.permission = permission;	}	public Prop<SecureUser, Object> getProp() {		return prop;	}	public void setProp(Prop<SecureUser, Object> prop) {		this.prop = prop;	}	public Long getAccountId() {		return accountId;	}	public void setAccountId(Long accountId) {		this.accountId = accountId;	}	public String getDomain() {		return domain;	}	public void setDomain(String domain) {		this.domain = domain;	}	public String getUsername() {		return username;	}	public void setUsername(String username) {		this.username = username;	}	public String getFullname() {		return fullname;	}	public void setFullname(String fullname) {		this.fullname = fullname;	}	public String getTitle() {		return title;	}	public void setTitle(String title) {		this.title = title;	}	public String getLang() {		return lang;	}	public void setLang(String lang) {		this.lang = lang;	}}